INSERT INTO product_reviews (user_id, product_id, rating, comment, created_at, updated_at)
VALUES
(2, 1, 5, 'Máy cầm rất đầm tay, viền titan sa mạc cực kỳ sang trọng. Nút Camera Control dùng tiện hơn hẳn khi quay video 4K 120fps.', NOW() - INTERVAL '5 days', NOW()),
(3, 1, 5, 'Màn hình 6.9 inch viền siêu mỏng nhìn rất đã mắt, pin dùng cả ngày dài lướt web làm việc đến tối vẫn còn 35%. Hàng VN/A chuẩn seal!', NOW() - INTERVAL '3 days', NOW()),
(4, 1, 4, 'Chất lượng hoàn thiện tuyệt hảo, camera tele 5x chụp chân dung xóa phông rất tự nhiên. Giao hàng hỏa tốc trong 2h rất ấn tượng.', NOW() - INTERVAL '1 day', NOW()),

(2, 2, 5, 'Galaxy AI khoanh tròn tìm kiếm tiện dụng kinh khủng. Bút S-Pen ghi chú trực tiếp lên màn hình cực mượt. Rất đáng đồng tiền bát gạo.', NOW() - INTERVAL '4 days', NOW()),
(5, 2, 5, 'Màn hình phẳng chống lóa Gorilla Armor là nâng cấp đáng giá nhất năm nay, đi ngoài trời nắng gắt nhìn vẫn trong vắt.', NOW() - INTERVAL '2 days', NOW()),

(4, 3, 5, 'Cỗ máy đỉnh cao cho lập trình viên. Mình chạy Docker 10 containers song song và build project Spring Boot mượt mà không hề nghe tiếng quạt.', NOW() - INTERVAL '6 days', NOW()),
(6, 3, 5, 'Màn hình XDR chuẩn màu tuyệt đối cho dân thiết kế, màu Space Black không bị bám vân tay như bản M2 trước.', NOW() - INTERVAL '3 days', NOW()),

(3, 5, 5, 'Màn hình OLED 240Hz màu sắc cực đỉnh, vừa mỏng nhẹ mang đi cà phê vừa chiến mượt Black Myth Wukong đồ họa max setting.', NOW() - INTERVAL '2 days', NOW()),
(4, 7, 5, 'Chống ồn tốt nhất phân khúc, đeo 4 tiếng trên máy bay không hề bị bí tai. Âm trường rộng, bass sâu và chắc chắn.', NOW() - INTERVAL '5 days', NOW()),
(2, 11, 5, 'Con lăn MagSpeed cuộn tài liệu Excel 10.000 dòng trong tích tắc. Cảm giác cầm nắm công thái học ôm trọn lòng bàn tay cực sướng.', NOW() - INTERVAL '7 days', NOW()),
(5, 12, 5, 'Switch Tactile Quiet gõ rất êm và có lực phản hồi tốt, không làm phiền đồng nghiệp xung quanh. Đèn nền thông minh tự sáng tiện lợi.', NOW() - INTERVAL '4 days', NOW())
ON CONFLICT (user_id, product_id) DO UPDATE SET
    rating = EXCLUDED.rating,
    comment = EXCLUDED.comment;


-- 6. SEED PRODUCT_STOREFRONT_CONTENTS (Nội dung marketing, chính sách, khuyến mãi, media)
INSERT INTO product_storefront_contents (product_id, content)
VALUES
(1, '{"storySections": [{"heading": "Thiết kế Titan cấp 5 siêu nhẹ và viền màn hình mỏng nhất lịch sử Apple", "body": "iPhone 16 Pro Max sở hữu lớp vỏ titan cấp 5 với bề mặt hoàn thiện vi phun mới đầy tinh xảo, tỷ lệ độ bền trên trọng lượng vượt trội hơn bất kỳ kim loại nào. Viền bezel mỏng kỷ lục kết hợp cùng màn hình Super Retina XDR 6.9 inch mở ra trải nghiệm hiển thị thị giác choáng ngợp chưa từng có.", "imageUrl": "https://images.unsplash.com/photo-1592750475338-74b7b21085ab?w=1000&auto=format&fit=crop&q=80", "imageCaption": "Vẻ đẹp hoàn mỹ của Titan Sa Mạc và màn hình Super Retina XDR 6.9 inch"}, {"heading": "Đột phá nút Điều Khiển Camera (Camera Control) - Nhiếp ảnh trong tầm tay", "body": "Nút Camera Control xúc giác cảm biến lực mới giúp bạn tương tác với máy ảnh chuyên nghiệp tức thì. Chỉ cần trượt nhẹ ngón tay để chuyển đổi mượt mà giữa các ống kính, khẩu độ, điều chỉnh độ phơi sáng hay lấy nét theo thời gian thực như một chiếc máy ảnh cơ DSLR.", "imageUrl": "https://images.unsplash.com/photo-1510557880182-3d4d3cba35a5?w=1000&auto=format&fit=crop&q=80", "imageCaption": "Nút bấm xúc giác điện dung đa năng cho cảm giác chụp ảnh chân thực"}, {"heading": "Sức mạnh vi xử lý Apple A18 Pro 3nm dẫn đầu kỷ nguyên Apple Intelligence", "body": "Với kiến trúc bóng bán dẫn 3nm thế hệ thứ 2, Apple A18 Pro nâng cấp băng thông bộ nhớ lên 17% và sở hữu Neural Engine 16 nhân tối ưu cho các mô hình AI trực tiếp trên máy. Trải nghiệm đồ họa Ray Tracing phần cứng mượt mà gấp đôi thế hệ trước khi chiến các tựa game AAA đỉnh cao.", "imageUrl": "https://images.unsplash.com/photo-1550745165-9bc0b252726f?w=1000&auto=format&fit=crop&q=80", "imageCaption": "Chip xử lý di động mạnh mẽ và tiết kiệm năng lượng nhất từng có"}], "media": {"reviewVideoUrl": "https://www.youtube.com/watch?v=0hQf7Y1p5c0", "unboxingVideoUrl": "https://www.youtube.com/watch?v=0hQf7Y1p5c0", "unboxingDescription": "Bộ sản phẩm chính hãng gồm: Thân máy iPhone 16 Pro Max VN/A nguyên seal, Cáp sạc bọc dù USB-C sang USB-C (1m), Sách hướng dẫn và Que chọc SIM.", "view360Url": "https://images.unsplash.com/photo-1592750475338-74b7b21085ab?w=1000"}, "promotions": [{"id": "ip-promo-1", "title": "Giảm ngay 1.000.000đ khi thanh toán qua ví VNPAY-QR hoặc MoMo", "description": "Nhập mã TECHSTORE1M tại bước thanh toán online hoặc quét mã tại cửa hàng", "partnerName": "VNPAY", "discountAmount": 1000000}, {"id": "ip-promo-2", "title": "Ưu đãi tựu trường: Giảm thêm 500.000đ cho Học sinh - Sinh viên", "description": "Chỉ cần xuất trình thẻ HSSV hoặc tài khoản ứng dụng VNeID", "partnerName": "TechStore Education", "discountAmount": 500000}, {"id": "ip-promo-3", "title": "Tặng gói Bảo Hành VIP TechStore Care+ 12 Tháng (Rơi vỡ & Vào nước)", "description": "Bảo vệ toàn diện phần cứng thiết bị, đổi máy mới trong 30 ngày nếu hư hại", "partnerName": "Apple Care+ Authorized"}], "paymentOffers": [{"id": "ip-pay-1", "title": "Hoàn tiền 5% tối đa 600.000đ khi thanh toán thẻ tín dụng Techcombank / VPBank", "description": "Áp dụng cho đơn hàng từ 25.000.000đ trở lên", "partnerName": "Techcombank"}], "bundleOffers": [{"id": "ip-bundle-1", "title": "Củ sạc nhanh Apple 30W USB-C chính hãng", "description": "Mua kèm máy giảm giá sốc từ 690.000đ chỉ còn 390.000đ", "originalPrice": 690000, "price": 390000}, {"id": "ip-bundle-2", "title": "Ốp lưng Apple MagSafe trong suốt kháng ố vàng", "description": "Mua kèm máy tiết kiệm ngay 40% chi phí", "originalPrice": 490000, "price": 290000}], "installmentPlans": [{"providerName": "Thẻ tín dụng (Visa / Mastercard)", "months": 12, "interestRatePercent": 0, "monthlyPayment": 2915833, "downPayment": 0, "terms": "0% lãi suất, 0đ phụ phí chuyển đổi kỳ hạn 6 - 12 tháng tại 25 ngân hàng đối tác"}, {"providerName": "Công ty tài chính Home Credit", "months": 6, "interestRatePercent": 0, "monthlyPayment": 4082166, "downPayment": 10497000, "terms": "Trả trước 30%, duyệt hồ sơ nhanh trong 10 phút chỉ với CCCD gắn chip"}], "tradeInOffers": [{"deviceModel": "iPhone 15 Pro Max 256GB cũ", "maximumSubsidy": 2000000, "minimumTopUp": 8000000, "maximumTopUp": 11000000, "condition": "Máy đẹp 99%, đầy đủ chức năng, pin trên 85%", "terms": "Thu cũ giá cao nhất thị trường, trợ giá thêm 2.000.000đ lên đời iPhone 16 Pro Max"}], "storePolicy": {"officialProductText": "Hàng chính hãng Apple VN/A - Nguyên seal 100%", "warrantyText": "Bảo hành 12 tháng tại các trung tâm bảo hành ủy quyền Apple AASP toàn quốc", "exchangeText": "Hư gì đổi nấy trong 30 ngày đầu tiên nếu phát sinh lỗi từ nhà sản xuất", "shippingText": "Giao hàng hỏa tốc trong 2 giờ tại nội thành Hà Nội & TP. Hồ Chí Minh", "hotline": "1800 6868", "hotlineHours": "08:00 - 21:30 hàng ngày (Miễn phí cước gọi)"}, "faqs": [{"question": "Hộp iPhone 16 Pro Max chính hãng có bao gồm củ sạc không?", "answer": "Theo chính sách bảo vệ môi trường toàn cầu của Apple, trong hộp sản phẩm bao gồm thân máy, cáp sạc bọc dù USB-C sang USB-C và tài liệu hướng dẫn. Bạn có thể chọn mua kèm củ sạc chính hãng 30W với giá giảm tới 40%."}, {"question": "Sản phẩm có được bảo hành chính hãng tại Việt Nam không?", "answer": "Tất cả máy bán tại TechStore là phiên bản chính hãng VN/A, được bảo hành toàn diện 12 tháng tại toàn bộ trung tâm Apple Authorized Service Provider (AASP) trên lãnh thổ Việt Nam."}, {"question": "Tôi có thể mua trả góp 0% bằng những hình thức nào?", "answer": "TechStore hỗ trợ 2 hình thức: Trả góp qua thẻ tín dụng của 25 ngân hàng liên kết (kỳ hạn 3-12 tháng, không mất phí) hoặc trả góp duyệt hồ sơ CCCD online qua Home Credit / FE Credit."}], "cityAvailability": [{"cityCode": "HN", "cityName": "Hà Nội", "storeCount": 8, "stockCount": 45, "deliveryEstimate": "Giao siêu tốc 2 giờ"}, {"cityCode": "HCM", "cityName": "TP. Hồ Chí Minh", "storeCount": 12, "stockCount": 78, "deliveryEstimate": "Giao siêu tốc 2 giờ"}, {"cityCode": "DN", "cityName": "Đà Nẵng", "storeCount": 3, "stockCount": 18, "deliveryEstimate": "Giao trong ngày"}], "comparisonProductIds": [2, 10]}'::jsonb),
(2, '{"storySections": [{"heading": "Kỷ nguyên Galaxy AI - Trí tuệ nhân tạo toàn diện trên thiết bị di động", "body": "Galaxy S24 Ultra mở ra kỷ nguyên mới với Galaxy AI tích hợp: Khoanh tròn để tìm kiếm (Circle to Search với Google), Dịch cuộc gọi trực tiếp hai chiều Live Translate thời gian thực, và Trợ lý Note tóm tắt tài liệu thông minh giúp bạn làm việc năng suất vượt bậc.", "imageUrl": "https://images.unsplash.com/photo-1610945265064-0e34e5519bbf?w=1000&auto=format&fit=crop&q=80", "imageCaption": "Kỷ nguyên thông minh cùng Galaxy AI và bút S-Pen quyền năng"}, {"heading": "Màn hình phẳng Dynamic AMOLED 2X chống chói Corning Gorilla Armor", "body": "Đột phá với màn hình phẳng hoàn toàn giúp tối ưu hóa diện tích vẽ viết với bút S-Pen. Lớp kính Corning Gorilla Armor độc quyền giảm phản xạ ánh sáng tới 75% và độ sáng đỉnh 2.600 nits giúp bạn quan sát sắc nét ngay cả dưới ánh nắng gắt nhiệt đới.", "imageUrl": "https://images.unsplash.com/photo-1546868871-7041f2a55e12?w=1000&auto=format&fit=crop&q=80", "imageCaption": "Kính cường lực chống phản xạ ánh sáng đầu tiên trên thế giới"}], "media": {"reviewVideoUrl": "https://www.youtube.com/watch?v=0hQf7Y1p5c0", "unboxingDescription": "Hộp sản phẩm gồm: Thân máy Galaxy S24 Ultra kèm bút S-Pen, Cáp sạc Type-C sang Type-C, Que lấy SIM, Sách hướng dẫn.", "view360Url": "https://images.unsplash.com/photo-1610945265064-0e34e5519bbf?w=1000"}, "promotions": [{"id": "ss-promo-1", "title": "Giảm ngay 1.500.000đ khi thanh toán qua Samsung Pay hoặc VNPay", "description": "Áp dụng độc quyền cho khách hàng mua Galaxy S24 Ultra", "partnerName": "Samsung Pay", "discountAmount": 1500000}, {"id": "ss-promo-2", "title": "Tặng củ sạc siêu nhanh Samsung 45W Type-C trị giá 790.000đ", "description": "Quà tặng chính hãng đi kèm máy số lượng có hạn", "partnerName": "Samsung Vietnam"}], "paymentOffers": [{"id": "ss-pay-1", "title": "Ưu đãi thẻ tín dụng HSBC / Shinhan Bank hoàn 800.000đ", "partnerName": "Shinhan Bank"}], "bundleOffers": [{"id": "ss-bundle-1", "title": "Tai nghe Galaxy Buds3 Pro chính hãng", "description": "Mua kèm S24 Ultra giảm giá từ 5.490.000đ còn 3.990.000đ", "originalPrice": 5490000, "price": 3990000}], "installmentPlans": [{"providerName": "Thẻ tín dụng", "months": 12, "interestRatePercent": 0, "monthlyPayment": 2499166, "downPayment": 0, "terms": "0% lãi suất, kỳ hạn linh hoạt 6 - 12 tháng"}], "tradeInOffers": [{"deviceModel": "Galaxy S23 Ultra cũ", "maximumSubsidy": 2500000, "minimumTopUp": 7000000, "maximumTopUp": 9500000, "condition": "Máy hoạt động tốt, màn hình không ám ố", "terms": "Thu cũ trợ giá tốt nhất thị trường"}], "storePolicy": {"officialProductText": "Hàng chính hãng Samsung Việt Nam - Nguyên seal", "warrantyText": "Bảo hành 12 tháng tại hệ thống TTBH Samsung trên toàn quốc", "exchangeText": "1 đổi 1 trong 30 ngày nếu phát sinh lỗi phần cứng", "shippingText": "Giao hàng hỏa tốc trong 2 giờ tại nội thành Hà Nội & TP. HCM", "hotline": "1800 6868", "hotlineHours": "08:00 - 21:30 hàng ngày"}, "faqs": [{"question": "Bút S-Pen có được gắn sẵn trong thân máy không?", "answer": "Có, bút S-Pen được tích hợp nguyên bản trong thân máy Galaxy S24 Ultra, hỗ trợ đầy đủ tính năng Bluetooth điều khiển từ xa và ghi chú nhanh khi tắt màn hình."}, {"question": "Tính năng Galaxy AI có miễn phí không?", "answer": "Samsung cam kết cung cấp miễn phí các tính năng Galaxy AI cốt lõi cho thiết bị đến hết năm 2025."}], "cityAvailability": [{"cityCode": "HN", "cityName": "Hà Nội", "storeCount": 10, "stockCount": 35, "deliveryEstimate": "Giao siêu tốc 2 giờ"}, {"cityCode": "HCM", "cityName": "TP. Hồ Chí Minh", "storeCount": 15, "stockCount": 60, "deliveryEstimate": "Giao siêu tốc 2 giờ"}, {"cityCode": "DN", "cityName": "Đà Nẵng", "storeCount": 4, "stockCount": 15, "deliveryEstimate": "Giao trong ngày"}], "comparisonProductIds": [1, 10]}'::jsonb),
(3, '{"storySections": [{"heading": "Hiệu năng đồ họa bùng nổ cùng chip Apple M3 Pro thế hệ mới", "body": "Được xây dựng trên tiến trình 3nm đột phá, Apple M3 Pro mang tới 11 nhân CPU mạnh mẽ kết hợp cùng 14 nhân GPU kiến trúc Dynamic Caching và công nghệ Mesh Shading, Hardware Ray Tracing giúp xử lý mượt mà cảnh dựng 3D Maya, Blender và biên tập đa luồng video 8K ProRes trong Final Cut Pro.", "imageUrl": "https://images.unsplash.com/photo-1517336714731-489689fd1ca8?w=1000&auto=format&fit=crop&q=80", "imageCaption": "Màu Đen Không Gian (Space Black) mạ anode hạn chế bám dấu vân tay tối ưu"}, {"heading": "Màn hình Liquid Retina XDR - Chuẩn mực điện ảnh cho nhà sáng tạo", "body": "Màn hình Mini-LED đỉnh cao hỗ trợ độ sáng liên tục 1.000 nits toàn màn hình và 1.600 nits độ sáng HDR đỉnh cao. Tần số quét ProMotion 120Hz linh hoạt và dải màu rộng DCI-P3 đáp ứng khắt khe các tiêu chuẩn kiểm duyệt màu sắc điện ảnh Hollywood.", "imageUrl": "https://images.unsplash.com/photo-1525547719571-a2d4ac8945e2?w=1000&auto=format&fit=crop&q=80", "imageCaption": "Màn hình Liquid Retina XDR với hơn 10.000 bóng đèn Mini-LED độc lập"}], "media": {"reviewVideoUrl": "https://www.youtube.com/watch?v=0hQf7Y1p5c0", "unboxingDescription": "Bộ sản phẩm gồm: MacBook Pro 14 inch M3 Pro, Củ sạc USB-C 70W hoặc 96W, Cáp sạc bọc dù MagSafe 3 (2m), Tài liệu hướng dẫn sử dụng.", "view360Url": "https://images.unsplash.com/photo-1517336714731-489689fd1ca8?w=1000"}, "promotions": [{"id": "mbp-promo-1", "title": "Tặng Túi chống sốc Tomtoc Premium trị giá 890.000đ", "description": "Túi chống sốc đạt chuẩn quân đội bảo vệ hoàn hảo cho MacBook Pro", "partnerName": "Tomtoc"}, {"id": "mbp-promo-2", "title": "Giảm ngay 1.000.000đ qua cổng thanh toán VNPay", "discountAmount": 1000000, "partnerName": "VNPAY"}], "paymentOffers": [{"id": "mbp-pay-1", "title": "Giảm thêm 500.000đ khi thanh toán thẻ tín dụng Shinhan Bank", "partnerName": "Shinhan Bank"}], "bundleOffers": [{"id": "mbp-bundle-1", "title": "Chuột Magic Mouse Apple Black Edition", "description": "Mua kèm máy giảm giá còn 1.690.000đ (Giá gốc 2.290.000đ)", "originalPrice": 2290000, "price": 1690000}], "installmentPlans": [{"providerName": "Thẻ tín dụng", "months": 12, "interestRatePercent": 0, "monthlyPayment": 4165833, "downPayment": 0, "terms": "0% lãi suất, chuyển đổi miễn phí"}], "tradeInOffers": [{"deviceModel": "MacBook Pro 14 M1 Pro cũ", "maximumSubsidy": 2500000, "minimumTopUp": 18000000, "maximumTopUp": 22000000, "condition": "Máy đẹp, pin trên 80%", "terms": "Thu cũ đổi mới hỗ trợ trả góp khoản tiền bù"}], "storePolicy": {"officialProductText": "Hàng chính hãng Apple VN - Đầy đủ hóa đơn VAT", "warrantyText": "Bảo hành 12 tháng tại các trung tâm Apple Authorized Service Provider", "exchangeText": "1 đổi 1 trong 30 ngày nếu phát hiện lỗi phần cứng nhà sản xuất", "shippingText": "Giao hàng hỏa tốc trong 2 giờ khu vực nội thành", "hotline": "1800 6868", "hotlineHours": "08:00 - 21:30 hàng ngày"}, "faqs": [{"question": "Máy có chạy mượt mà các tác vụ lập trình Backend và Docker không?", "answer": "Hoàn toàn mượt mà. Với 18GB/36GB Unified Memory tốc độ 150GB/s và 11 nhân CPU, máy có thể chạy mượt mà nhiều container Docker, IDE JetBrains, VS Code và máy ảo song song."}], "cityAvailability": [{"cityCode": "HN", "cityName": "Hà Nội", "storeCount": 6, "stockCount": 20, "deliveryEstimate": "Giao siêu tốc 2 giờ"}, {"cityCode": "HCM", "cityName": "TP. Hồ Chí Minh", "storeCount": 9, "stockCount": 35, "deliveryEstimate": "Giao siêu tốc 2 giờ"}], "comparisonProductIds": [4, 5]}'::jsonb),
